\set ON_ERROR_STOP on
BEGIN READ ONLY;
\copy (SELECT ordinal_position, column_name, data_type, udt_name, is_nullable FROM information_schema.columns WHERE table_schema='public' AND table_name='rag_chunks' ORDER BY ordinal_position) TO 'C:/Users/mamen/Documents/Python/RAGChatBot/evaluation_v2/run_20260809_170051/logs/db_schema.csv' WITH (FORMAT CSV, HEADER TRUE, ENCODING 'UTF8')
\copy (SELECT doc_id, chunk_id, page_num, topic, source, lang, content, created_at FROM rag_chunks ORDER BY doc_id, chunk_id) TO 'C:/Users/mamen/Documents/Python/RAGChatBot/evaluation_v2/run_20260809_170051/logs/db_chunks.csv' WITH (FORMAT CSV, HEADER TRUE, ENCODING 'UTF8')
\copy (SELECT count(DISTINCT doc_id) AS num_documents, count(*) AS num_chunks, count(*) FILTER (WHERE doc_id IS NULL) AS null_doc_id, count(*) FILTER (WHERE chunk_id IS NULL) AS null_chunk_id, count(*) FILTER (WHERE content IS NULL OR btrim(content)='') AS null_or_empty_content, count(*) FILTER (WHERE topic IS NULL) AS null_topic, count(*) FILTER (WHERE source IS NULL) AS null_source, count(*) FILTER (WHERE lang IS NULL) AS null_lang, count(*) FILTER (WHERE page_num IS NULL) AS null_page_num, count(*) FILTER (WHERE embedding IS NULL) AS null_embedding, min(created_at) AS min_created_at, max(created_at) AS max_created_at FROM rag_chunks) TO 'C:/Users/mamen/Documents/Python/RAGChatBot/evaluation_v2/run_20260809_170051/logs/db_profile_before.csv' WITH (FORMAT CSV, HEADER TRUE, ENCODING 'UTF8')
\copy (WITH queries(question_id, claim_id, query_type, query_text) AS (VALUES ('Q001','','question','¿Qué es la astenia?'),('Q002','','question','¿Qué debe hacer un paciente si tiene una temperatura de 38º o más?'),('Q003','','question','¿Cuál es el trastorno del sueño más común en pacientes con cáncer?'),('Q004','','question','¿Cómo se define la mucositis?'),('Q005','','question','¿Cuánto tiempo suele durar una sesión de administración de quimioterapia?'),('Q006','','question','¿Qué es la Neutropenia?'),('Q007','','question','¿Siempre se cae el cabello con los tratamientos de quimioterapia?'),('Q008','','question','¿En qué momento suele caer el cabello tras el tratamiento?'),('Q009','','question','¿Qué medicamento de quimioterapia se asocia a la TDA en el cáncer de próstata hormono-sensible meastásica CPHSm?'),('Q010','','question','¿Para qué sirve el fármaco Denosumab?'),('Q011','','question','¿Cuál es el principal efecto adverso de la Apalutamida?'),('Q012','','question','¿cómo suele tratarse el cáncer de próstata resistente a la castración no metastásico?'),('Q013','','question','¿qué tipos de cáncer de próstata se tratan con terapia de privación de andrógenos?'),('Q014','','question','¿Para qué sirve el Radium-223?'),('Q015','','question','¿Cómo afecta la prostatectomía radical a la eyaculación?'),('Q016','','question','¿Qué dieta se recomienda para minimizar los efectos de la quimioterapia?'),('Q017','','question','¿Qué síntoma se denomina "tinnitus"?'),('Q018','','question','¿Para qué sirve el test PAM50 (Prosigna)?'),('Q019','','question','¿Cuáles son los efectos secundarios del tamoxifeno?'),('Q020','','question','¿Qué recomendaciones específicas hay para pacientes tratadas con tamoxifeno?'),('Q021','','question','¿Qué síntomas causa la falta de estrógenos?'),('Q022','','question','¿Se puede usar antidepresivos en pacientes con cancer de mama?'),('Q023','','question','¿Qué efecto tiene la quimioterapia sobre los ovarios?'),('Q024','','question','¿Qué es la dispareunia?'),('Q025','','question','¿Puedo quedarme embarazada después de un tratamiento de cancer?'),('Q026','','question','¿cuáles son los factores de riesgo del cancer de mama?'),('Q027','','question','¿Cómo se pueden solicitar pruebas de imagen de mama y qué información es necesaria?'),('Q028','','question','¿Cuáles son las mutaciones genéticas más frecuentes en cáncer de mama y ovario hereditario?'),('Q029','','question','¿Qué es la pancitopenia?'),('Q030','','question','¿Qué es la disnea?'),('Q031','','question','¿Qué es la proteinuria?')), configs(ts_config) AS (VALUES ('simple'),('spanish'),('english')) SELECT q.question_id, q.claim_id, q.query_type, q.query_text, 'lexical_' || cfg.ts_config AS retrieval_method, hit.retrieval_rank, hit.retrieval_score, 'ts_rank_cd' AS score_type, cfg.ts_config, hit.doc_id, hit.chunk_id, hit.page_num, hit.topic, hit.source, hit.lang, hit.content FROM queries q CROSS JOIN configs cfg CROSS JOIN LATERAL (SELECT c.doc_id, c.chunk_id, c.page_num, c.topic, c.source, c.lang, c.content, ts_rank_cd(to_tsvector(cfg.ts_config::regconfig, c.content), plainto_tsquery(cfg.ts_config::regconfig, q.query_text)) AS retrieval_score, row_number() OVER (ORDER BY ts_rank_cd(to_tsvector(cfg.ts_config::regconfig, c.content), plainto_tsquery(cfg.ts_config::regconfig, q.query_text)) DESC, c.doc_id, c.chunk_id) AS retrieval_rank FROM rag_chunks c WHERE to_tsvector(cfg.ts_config::regconfig, c.content) @@ plainto_tsquery(cfg.ts_config::regconfig, q.query_text) ORDER BY retrieval_score DESC, c.doc_id, c.chunk_id LIMIT 100) hit ORDER BY q.question_id, q.query_type, q.claim_id, cfg.ts_config, hit.retrieval_rank) TO 'C:/Users/mamen/Documents/Python/RAGChatBot/evaluation_v2/run_20260809_170051/logs/lexical_pool.csv' WITH (FORMAT CSV, HEADER TRUE, ENCODING 'UTF8')
COMMIT;